package br.edu.cesar.treinoconecta.treinoconectacore.infraestrutura.core.aula;

import java.time.*;import java.util.*;import org.springframework.jdbc.core.*;import org.springframework.data.domain.*;
import br.edu.cesar.treinoconecta.treinoconectacore.aplicacao.core.aula.spi.IAulaAplicacaoRepositorio;import br.edu.cesar.treinoconecta.treinoconectacore.aplicacao.core.aulasdesafios.*;
import dev.sauloaraujo.d5.framework.infraestrutura.AgregadoAplicacaoRepositorioAbstrato;

public final class AulaAplicacaoRepositorio extends AgregadoAplicacaoRepositorioAbstrato<AulasDesafiosDados.AulaLinha,AulasDesafiosOrdenacao,AulasDesafiosConsulta> implements IAulaAplicacaoRepositorio{
 private final JdbcTemplate jdbc;public AulaAplicacaoRepositorio(JdbcTemplate jdbc){this.jdbc=Objects.requireNonNull(jdbc);}
 protected Page<AulasDesafiosDados.AulaLinha> pesquisar(AulasDesafiosConsulta consulta,Pageable pagina){var linhas=aulas(Optional.empty(),Optional.empty(),Optional.empty(),"");int inicio=Math.min((int)pagina.getOffset(),linhas.size());int fim=Math.min(inicio+pagina.getPageSize(),linhas.size());return new PageImpl<>(linhas.subList(inicio,fim),pagina,linhas.size());}
 protected String paraPropriedadeOrdenacao(AulasDesafiosOrdenacao ordenacao){return "data";}
 public List<AulasDesafiosDados.AulaLinha> aulas(Optional<LocalDate> data,Optional<String> modalidade,Optional<String> busca,String usuario){StringBuilder sql=new StringBuilder("select a.AUL_ID,a.AUL_TITULO,a.AUL_MODALIDADE,a.AUL_DESCRICAO,a.AUL_DATA,a.AUL_INICIO,a.AUL_FIM,a.AUL_LIMITE,a.AUL_STATUS,a.PRF_ID,p.PRF_NOME,(select count(*) from AIN_INSCRICAO_AULA i where i.AUL_ID=a.AUL_ID and i.AIN_STATUS='AGENDADO') ocupacao,exists(select 1 from AIN_INSCRICAO_AULA i join ALU_ALUNO u on u.ALU_ID=i.ALU_ID where i.AUL_ID=a.AUL_ID and i.AIN_STATUS='AGENDADO' and u.ALU_USUARIO=?) inscrito from AUL_AULA a join PRF_PROFISSIONAL p on p.PRF_ID=a.PRF_ID where 1=1");var args=new ArrayList<Object>();args.add(usuario);data.ifPresent(x->{sql.append(" and a.AUL_DATA=?");args.add(x);});modalidade.filter(x->!x.isBlank()).ifPresent(x->{sql.append(" and lower(a.AUL_MODALIDADE)=lower(?)");args.add(x);});busca.filter(x->!x.isBlank()).ifPresent(x->{sql.append(" and (lower(a.AUL_TITULO) like lower(?) or lower(a.AUL_MODALIDADE) like lower(?))");args.add("%"+x+"%");args.add("%"+x+"%");});sql.append(" order by a.AUL_DATA,a.AUL_INICIO,a.AUL_ID");return jdbc.query(sql.toString(),aulaMapper(),args.toArray());}
 public Optional<AulasDesafiosDados.AulaLinha> aula(long id,String usuario){return jdbc.query("select a.AUL_ID,a.AUL_TITULO,a.AUL_MODALIDADE,a.AUL_DESCRICAO,a.AUL_DATA,a.AUL_INICIO,a.AUL_FIM,a.AUL_LIMITE,a.AUL_STATUS,a.PRF_ID,p.PRF_NOME,(select count(*) from AIN_INSCRICAO_AULA i where i.AUL_ID=a.AUL_ID and i.AIN_STATUS='AGENDADO') ocupacao,exists(select 1 from AIN_INSCRICAO_AULA i join ALU_ALUNO u on u.ALU_ID=i.ALU_ID where i.AUL_ID=a.AUL_ID and i.AIN_STATUS='AGENDADO' and u.ALU_USUARIO=?) inscrito from AUL_AULA a join PRF_PROFISSIONAL p on p.PRF_ID=a.PRF_ID where a.AUL_ID=?",aulaMapper(),usuario,id).stream().findFirst();}
 public List<AulasDesafiosDados.InscricaoLinha> minhasAulas(String usuario){return jdbc.query("select i.AIN_ID,a.AUL_TITULO,a.AUL_MODALIDADE,a.AUL_DATA,a.AUL_INICIO,p.PRF_NOME,case when i.AIN_STATUS='AGENDADO' and (a.AUL_DATA<current_date or (a.AUL_DATA=current_date and a.AUL_FIM<current_time)) then 'CONCLUIDO' else i.AIN_STATUS end,i.AIN_REGISTRO,u.ALU_NOME from AIN_INSCRICAO_AULA i join AUL_AULA a on a.AUL_ID=i.AUL_ID join PRF_PROFISSIONAL p on p.PRF_ID=a.PRF_ID join ALU_ALUNO u on u.ALU_ID=i.ALU_ID where u.ALU_USUARIO=? order by i.AIN_REGISTRO desc",inscricaoMapper(),usuario);}
 public List<AulasDesafiosDados.InscricaoLinha> inscritos(long aula){return jdbc.query("select i.AIN_ID,a.AUL_TITULO,a.AUL_MODALIDADE,a.AUL_DATA,a.AUL_INICIO,p.PRF_NOME,i.AIN_STATUS,i.AIN_REGISTRO,u.ALU_NOME from AIN_INSCRICAO_AULA i join AUL_AULA a on a.AUL_ID=i.AUL_ID join PRF_PROFISSIONAL p on p.PRF_ID=a.PRF_ID join ALU_ALUNO u on u.ALU_ID=i.ALU_ID where i.AUL_ID=? order by i.AIN_REGISTRO",inscricaoMapper(),aula);}
 public List<AulasDesafiosDados.NotificacaoLinha> notificacoes(String usuario){String q="select n.NOT_ID,a.AUL_TITULO,u.ALU_NOME,n.NOT_MENSAGEM,n.NOT_REGISTRO,n.NOT_LIDA from NOT_NOTIFICACAO_AULA n join AUL_AULA a on a.AUL_ID=n.AUL_ID join ALU_ALUNO u on u.ALU_ID=n.ALU_ID where (?='' or u.ALU_USUARIO=?) order by n.NOT_REGISTRO desc";return jdbc.query(q,(r,n)->new AulasDesafiosDados.NotificacaoLinha(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getObject(5,OffsetDateTime.class),r.getBoolean(6)),usuario,usuario);}
 public List<AulasDesafiosDados.PessoaLinha> professores(){return jdbc.query("select PRF_ID,PRF_NOME from PRF_PROFISSIONAL where PRF_PROFESSOR=true and PRF_SITUACAO='ATIVO' order by PRF_NOME",(r,n)->new AulasDesafiosDados.PessoaLinha(r.getLong(1),r.getString(2)));}
 private RowMapper<AulasDesafiosDados.AulaLinha> aulaMapper(){return (r,n)->new AulasDesafiosDados.AulaLinha(r.getLong("AUL_ID"),r.getString("AUL_TITULO"),r.getString("AUL_MODALIDADE"),r.getString("AUL_DESCRICAO"),r.getDate("AUL_DATA").toLocalDate(),r.getTime("AUL_INICIO").toLocalTime(),r.getTime("AUL_FIM").toLocalTime(),r.getInt("AUL_LIMITE"),r.getInt("OCUPACAO"),r.getString("AUL_STATUS"),r.getLong("PRF_ID"),r.getString("PRF_NOME"),r.getBoolean("INSCRITO"));}
 private RowMapper<AulasDesafiosDados.InscricaoLinha> inscricaoMapper(){return (r,n)->new AulasDesafiosDados.InscricaoLinha(r.getLong(1),r.getString(2),r.getString(3),r.getDate(4).toLocalDate(),r.getTime(5).toLocalTime(),r.getString(6),r.getString(7),r.getObject(8,OffsetDateTime.class),r.getString(9));}
}
